<template><section class="content-card profile-card"><p class="eyebrow">ЛИЧНЫЙ КАБИНЕТ</p><h1>Мой профиль</h1><form @submit.prevent="save"><label>ФИО<InputText v-model="fio"/></label><label>Телефон<InputText v-model="telefon"/></label><Message v-if="message" :severity="ok?'success':'error'" :closable="false">{{message}}</Message><Button type="submit" label="Сохранить изменения" icon="pi pi-check"/></form></section></template>
<script>import InputText from 'primevue/inputtext';import Button from 'primevue/button';import Message from 'primevue/message';import{useAuthStore}from'@/stores/authStore';export default{components:{InputText,Button,Message},data(){const a=useAuthStore();return{auth:a,fio:a.user?.name||'',telefon:a.user?.telefon||'',message:'',ok:false}},methods:{async save(){this.ok=await this.auth.updateProfile({fio:this.fio,telefon:this.telefon});this.message=this.ok?'Данные сохранены':this.auth.errorMessage}}}</script>
